import styled from '@emotion/styled';
import { theme } from 'theme';

export const StyledDeepDiveHeaderContainer = styled.div({
  display: 'flex',
  justifyContent: 'space-between',
  width: '100%',
  alignItems: 'center',
  padding: ['0', theme.spacing['2']].join(' '),
});

export const StyledDeepDiveFilters = styled.div({
  display: 'flex',
  gap: theme.spacing['2'],
});
